import sys
import os
import random
import pandas as pd

# Add backend directory to Python path so we can import database
sys.path.append(os.path.abspath(os.path.join(os.path.dirname(__file__), "..")))

from database.connection import SessionLocal
from database.models import Question

def export_dataset():
    print("Connecting to the database...")
    db = SessionLocal()
    
    try:
        # Fetch all questions generated by our seed script
        questions = db.query(Question).filter(Question.source == "seed_db_script").all()
        print(f"Found {len(questions)} questions in the database.")
        
        if len(questions) == 0:
            print("No questions found! Make sure you ran seed_database_questions.py first.")
            return

        dataset = []
        for q in questions:
            # Construct the input prompt that FLAN-T5 will learn from
            # Example: "Generate a Medium difficulty interview question for a Backend Developer focusing on the skill: Docker."
            input_prompt = f"Generate a {q.difficulty} difficulty interview question for a {q.role} focusing on the skill: {q.skill}."
            
            # The target text is the actual question
            output_question = q.question_text
            
            dataset.append({
                "input_prompt": input_prompt,
                "output_question": output_question
            })
            
        # Shuffle the dataset
        random.shuffle(dataset)
        
        # Split into 80% train, 20% validation
        split_idx = int(len(dataset) * 0.8)
        train_data = dataset[:split_idx]
        val_data = dataset[split_idx:]
        
        # Save to CSV
        dataset_dir = os.path.join(os.path.dirname(__file__), "..", "dataset")
        os.makedirs(dataset_dir, exist_ok=True)
        
        train_csv_path = os.path.join(dataset_dir, "flan_t5_train.csv")
        val_csv_path = os.path.join(dataset_dir, "flan_t5_val.csv")
        
        pd.DataFrame(train_data).to_csv(train_csv_path, index=False)
        pd.DataFrame(val_data).to_csv(val_csv_path, index=False)
        
        print(f"Successfully exported {len(train_data)} rows to {train_csv_path}")
        print(f"Successfully exported {len(val_data)} rows to {val_csv_path}")
        print("You are now ready to run `train_flan_t5.py`!")
        
    except Exception as e:
        print(f"Error: {e}")
    finally:
        db.close()

if __name__ == "__main__":
    export_dataset()
